<script setup>
import {onMounted} from 'vue';import {useAuth} from '../stores/auth.js';import {useOrders} from '../stores/orders.js';import {money,useTask} from '../composables/useTask.js';const auth=useAuth(),store=useOrders();const {busy,error,run}=useTask();onMounted(()=>run(store.load))
</script><template><h2>My orders</h2><p v-if="error" role="alert">{{error}}</p><p v-if="!auth.me"><RouterLink to="/account">Sign in</RouterLink> to view orders.</p><template v-else><p v-if="!store.orders.length&&!busy">No orders yet.</p><article v-for="o in store.orders" :key="o.id" class="panel"><div class="line"><b>Order #{{String(o.id).slice(0,8)}}</b><span>{{o.status}}</span></div><div v-for="(f,i) in o.items" :key="i" class="line">{{f.name}} × {{f.quantity}}</div><div class="line"><b>{{money(o.total)}}</b><button v-if="String(o.status).toLowerCase()==='placed'" :disabled="busy" @click="run(()=>store.cancel(o.id))">Cancel order</button></div></article></template></template>
